import re

from taf.ul.bts_components import Smod

from taf.rfrl.procedures.resources.python.connections import get_ssh_connection_credentials
from taf.rfrl.procedures.resources.python.utilities import download_file_from_url, convert_to_list
from taf.rfrl.procedures.resources.python.logger import log_result, log_warning, log_input_and_output
from taf.rfrl.procedures.resources.python.wft.exceptions import WFTError
from taf.rfrl.procedures.resources.python.wft.remote_api import BuildEndpoint


class WFT(object):
    @log_input_and_output
    def get_version_of_nidd(self, package_name):
        """
        Gets version of nidd.

        :param package_name: name of nidd package
               E.g. input: 'NRBTSCL5G20B_2010_100'
        :type package_name: str
        :return: version of nidd package.
                E.g. output: '1.0.2'
        :rtype: str or None
        """
        version = self._get_sw_version()
        sub_builds = self._get_sub_builds_of_sw_package(version=version)
        nidd_sub_builds = []

        for sub_build in sub_builds:
            if "SBTS00" in version and sub_build["title"] == "NIDD_SBTS_NIDD":
                nidd_sub_builds = BuildEndpoint(
                    component="NIDD_SBTS_NIDD",
                    project=sub_build["project"],
                    version=sub_build["version"],
                ).sub_builds()

            elif sub_build["title"] == "NIDD_SBTS5GC_NIDD":
                nidd_sub_builds = BuildEndpoint(
                    component="NIDD_SBTS5GC_NIDD",
                    project=sub_build["project"],
                    version=sub_build["version"],
                ).sub_builds()

            for nidd_build in nidd_sub_builds:
                if package_name.split('_')[0] in nidd_build["version"]:
                    log_result("Version of nidd: {}".format(nidd_build["version"]))
                    return nidd_build["version"].split("_")[-1].replace("", ".")[1:-1]

            else:
                for nidd_build in nidd_sub_builds:
                    if sub_build['version'].split("_")[0] in nidd_build["version"]:
                        log_result("Version of nidd: {}".format(nidd_build["version"]))
                        return nidd_build["version"].split("_")[-1].replace("", ".")[1:-1]

        else:
            raise WFTError("No sub build named NIDD_SBTS_NIDD or NIDD_SBTS5GC_NIDD.")

    @log_input_and_output
    def get_scm_flag(self, rfsw):
        """
        Gets scm flag. In case of unknown rfsw equal to '?', unknown scm flag will be returned also as '?' sign.

        :param rfsw: radio software.
                E.g. input: 'FRM51.03.R13'
        :type rfsw: str
        :return: scm flag.
                E.g. output: 'rel5.1'
        :rtype: str
        :raise WFTError when details for given radio software will not be found.
        """
        if rfsw == '?':
            log_warning(f'Not possible to get scm flag due to unknown rfsw: {rfsw}. Please check if fault '
                        f'"SW Corrupted" ID:1850 is raised on RMOD.')
            return '?'

        version = self.get_valid_sw_version()
        sub_build = self._get_rfsw_sub_build(rfsw, version)

        if '5G_0.800.' in version or 'ENB_9999' in version or "ENB_0000" in version:
            build_attributes = BuildEndpoint(
                project=sub_build['project'],
                component=sub_build['component'],
                version=sub_build['version'],
            ).build_attributes()
            return build_attributes['bb_location'].split('/')[-1]

        return rfsw[:4]

    def get_valid_sw_version(self):
        """
        Checks if given version is not a knife, and if it is, gets its baseline SW build
        :return: valid SW build
        :rtype: str
        """
        version = self._get_sw_version()

        if self._check_if_sw_version_is_knife(version):
            return BuildEndpoint(project="", component="", version=version).get_baseline_sw_build()

        return version

    @log_input_and_output
    def get_latest_oran_rmod_plugin_version(self, rmod_product_code, allow_not_released_plugin=False):
        """
        Gets the latest released (optionally not released) RFMPlugin_O-RU plugin version for a given RMOD product code.

        :param rmod_product_code: RMOD product code, e.g., "475701A.103".
        :type rmod_product_code: str
        :param allow_not_released_plugin: If True, allows returning a non-released plugin version if no released version is found.
                                          Defaults to False.
        :type allow_not_released_plugin: bool
        :return: Latest released RFMPlugin_O-RU plugin version.
        :rtype: str
        :raise WFTError: If no released RFMPlugin_O-RU build is found for the specified RMOD product code.
        """
        plugins = self._get_oran_rmod_plugin_list(rmod_product_code=rmod_product_code, release_state="RELEASED")

        if not plugins or not plugins[0].get('version'):
            if allow_not_released_plugin:
                plugins = self._get_oran_rmod_plugin_list(rmod_product_code=rmod_product_code, release_state="NOT_RELEASED")

                if plugins and plugins[0].get('version'):
                    log_warning(f"Found non-released RFMPlugin_O-RU build for RMOD product code: {rmod_product_code}. "
                                f"Version: {plugins[0]['version']}")
                    return plugins[0]['version']

            raise WFTError(f"""No 'released'{" and 'not_released'" if allow_not_released_plugin else ""} RFMPlugin_O-RU build """
                           f"""found for RMOD product code: {rmod_product_code}""")

        return plugins[0]['version']

    @log_input_and_output
    def _get_oran_rmod_plugin_list(self, rmod_product_code, release_state):
        query = ("view[items]=1"
                 "&view[sorting_field]=created_at"
                 "&view[sorting_direction]=DESC"
                 "&view[columns][][id]=version"
                 "&view[columns][][id]=state"
                 "&view[view_filters_attributes][483095018292303][column]=version"
                 "&view[view_filters_attributes][483095018292303][operation]=cont_any"
                 f"&view[view_filters_attributes][483095018292303][value][]={rmod_product_code.replace('.', '-')}"
                 "&view[view_filters_attributes][428122650318056][column]=state"
                 "&view[view_filters_attributes][428122650318056][operation]=eq"
                 f"&view[view_filters_attributes][428122650318056][value][]={release_state}"
                 "&view[view_filters_attributes][587193142485817][column]=component"
                 "&view[view_filters_attributes][587193142485817][operation]=eq"
                 "&view[view_filters_attributes][587193142485817][value][]=RFMPlugin_O-RU&")

        return BuildEndpoint.custom_request(query).get('items', [])

    def get_download_links(self, project, component, version, regex=None):
        """
        Fetches download links from appropriate RFMPlugin_O-RU build from WFT download section.

        :param project: Project name, e.g., "Common".
        :type project: str
        :param component: Component name, e.g., "RFMPlugin_O-RU".
        :type component: str
        :param version: Version of the build, e.g., "RFMPlugin_O-RU_NK_475701A-103_0017".
        :type version: str
        :param regex: Optional regex to filter download links.
        :type regex: str
        :return: list of download links.
        :rtype: list[str]
        :raise WFTError: If no download links are found for the specified build.
        """
        download_links = self._get_download_links(project=project, component=component, version=version)
        if regex:
            download_links = [link for link in download_links if re.search(regex, link)]

        if not download_links:
            raise WFTError(f"No download links found for build: {version}")

        return download_links

    @log_input_and_output
    def get_project_and_component_from_build_version(self, version):
        """
        Get the project and component names from the build version.

        :param version: The build version. e.g "SBTS00_ENB_9999_250724_000009", "RF.FRU6.25R3.20250721.004"
        :type version: str
        :return: The project and component of provided build e.g.: {'project': 'Common', 'component': 'rf-FRU6'}
        :rtype: dict
        :raise WFTError: If the build version is not found in WFT.
        """
        build_info = self._search_build(version)
        if not build_info:
            raise WFTError(f"Build {version} not found in WFT.")

        info = {'project': build_info[0].get('deliverer.project.full_path'),
                'component': build_info[0].get('deliverer.title')}

        return info

    def get_rmod_sw_version_from_bts_sw_sub_builds(self, component, bts_sw=None):
        """
        Get from BTS software Sub bilds section RFSW version based on the component name.

        :param component: The component name, e.g., "rf-FRU6".
        :type component: str
        :param bts_sw: (Optional) BTS software version, e.g. "SBTS00_ENB_9999_250724_000009".
                       If not provided, the current BTS software version will be used.
        :type bts_sw: str
        :return: The RFSW version, e.g., "FRM51.03.R13".
        :rtype: str
        :raise WFTError: If the RFSW version is not found for the specified component.
        """

        if not bts_sw:
            bts_sw = self.get_valid_sw_version()

        sub_builds = self._get_sub_builds_of_sw_package(bts_sw)
        for sub_build in sub_builds:
            if sub_build['component'] == component:
                return sub_build['version']

        raise WFTError(f"RMOD SW version for component {component} not found.")

    def download_oran_rmod_sw_package(self, rmod_sw_component, save_path):
        """
        Downloads the O-RAN RMOD SW package based on the provided component name.

        :param rmod_sw_component: Component name of the RMOD SW build version, e.g. "rf-FRU6".
        :type rmod_sw_component: str
        :param save_path: The absolute path where the O-RAN RMOD SW package will be saved.
        :type save_path: str
        :return: The absolute path to the downloaded O-RAN RMOD SW package.
        :rtype: str
        :raise WFTError: If the O-RAN RMOD SW package is not found.
        """
        base_rmod_sw_version = self.get_rmod_sw_version_from_bts_sw_sub_builds(component=rmod_sw_component)
        base_rmod_sw_info = self.get_project_and_component_from_build_version(base_rmod_sw_version)
        download_links = self.get_download_links(
            project=base_rmod_sw_info['project'],
            component=base_rmod_sw_info['component'],
            version=base_rmod_sw_version,
            regex=rf'NK.{base_rmod_sw_version}.zip'
        )

        try:
            return self._try_download_from_links(download_links, save_path)
        except Exception as e:
            raise WFTError(f"Failed to download O-RAN RMOD SW package from base version: {base_rmod_sw_version}. Errors:\n{e}")

    def download_oran_rmod_plugin(self, plugin_version, save_path):
        """
        Downloads the O-RAN RMOD plugin.

        :param plugin_version: Plugin version, e.g. "RFMPlugin_O-RU_NK_475701A-103_0017".
        :type plugin_version: str
        :param save_path: The path where the plugin will be saved.
        :type save_path: str
        :return: The absolute path to the downloaded plugin.
        :rtype: str
        :raise WFTError: If no released RFMPlugin_O-RU build is found for the specified RMOD product code.
        """
        download_links = self._get_download_links(
            project='Common',
            component='RFMPlugin_O-RU',
            version=plugin_version
        )

        try:
            return self._try_download_from_links(download_links, save_path)
        except Exception as e:
            raise WFTError(f"Failed to download O-RAN plugin version: {plugin_version}. Errors:\n{e}")

    @staticmethod
    def get_custom_oran_plugin_version_for_rmod_product_code(rmod_product_code, custom_plugin_versions):
        """
        Gets custom O-RAN RMOD plugin version from provided dictionary with custom plugins versions.
        If custom plugin was not found for particular rmod product code or value of parameter 'custom_plugin_versions' is not
        a dictionary type, None is returned.
        :param rmod_product_code: rmod product code, e.g., "475701A.103".
        :type rmod_product_code: str
        :param custom_plugin_versions: Dictionary with custom plugin versions where key is RMOD product code and value is plugin version,
                                       e.g.: {'475701A.103': 'RFMPlugin_O-RU_NK_475701A-103_0017'}
        :type custom_plugin_versions: dict or None
        :return: Custom O-RAN RMOD plugin version or None if plugin version not found.
        :rtype: str or None
        """
        if isinstance(custom_plugin_versions, dict):
            return custom_plugin_versions.get(rmod_product_code)

    @log_input_and_output
    def _get_rfsw_sub_build(self, rfsw, version):
        sub_builds = self._get_sub_builds_of_sw_package(version)

        for sub_build in sub_builds:
            if sub_build['version'] == rfsw:
                return sub_build

        raise WFTError("Sub build with given version: {} dose not exist.".format(rfsw))

    @staticmethod
    @log_input_and_output
    def _get_sub_builds_of_sw_package(version):
        return BuildEndpoint(
            project="5G",
            component="BTS",
            version=version,
        ).sub_builds()

    @staticmethod
    def _get_sw_version():
        smod = Smod()
        credentials = get_ssh_connection_credentials()
        try:
            smod.connect_to(
                address=credentials["host"],
                username=credentials["username"],
                password=credentials["password"],
            )
            return smod.get_sw_version_from_targetbd()

        finally:
            smod.close_connection()

    @staticmethod
    def _check_if_sw_version_is_knife(version):
        pattern = r'^SBTS[0-9A-R]{0,4}_ENB_[0-9]{4}_[0-9]{6}_00'
        return not bool(re.match(pattern, version))

    def _get_download_links(self, project, component, version):
        """
        Fetches download links from WFT download section for a given project, component, and version.
        :param project: Project name, e.g., "Common".
        :type project: str
        :param component: Component name, e.g., "RFMPlugin_O-RU".
        :type component: str
        :param version: Version of the build, e.g., "RFMPlugin_O-RU_NK_475701A-103_0017".
        :type version: str
        :return: List of download links.
        :rtype: list[str]
        """
        download_links = []
        storages = BuildEndpoint(project=project, component=component, version=version).build_storages()

        for storage in storages:
            link = storage.get('storage').get('storage-items')[0].get('path')
            if link:
                download_links.append(link)

        return download_links

    def _search_build(self, version):
        """
        Search build version in WFT builds.
        :param version: The build version to search for, e.g. "SBTS00_ENB_9999_250724_000009".
        :type version: str
        :return: The response from the WFT API.
        :rtype: dict
        """
        query = ("&view[items]=1"
                 "&view[sorting_field]=created_at"
                 "&view[sorting_direction]=DESC"
                 "&view[columns][][id]=deliverer.project.full_path"
                 "&view[columns][][id]=deliverer.title"
                 "&view[columns][][id]=version"
                 "&view[columns][][id]=branch.title"
                 "&view[columns][][id]=state"
                 "&view[columns][][id]=planned_delivery_date"
                 "&view[columns][][id]=common_links"
                 "&view[columns][][id]=compare_link"
                 "&view[view_filters_attributes][870393755566292][column]=version"
                 "&view[view_filters_attributes][870393755566292][operation]=eq"
                 f"&view[view_filters_attributes][870393755566292][value][]={version}&")
        return BuildEndpoint.custom_request(query=query)['items']

    @log_input_and_output
    def _try_download_from_links(self, links, save_path):
        """
        Attempts to download a file from provided links.

        :param links: List of download links.
        :type links: str | list[str]
        :param save_path: Absolute path where the file will be saved.
        :type save_path: str
        :return: The absolute path to the downloaded file.
        :rtype: str
        :raise WFTError: If no link is successful for downloading.
        """
        links = convert_to_list(links)
        errors = []
        for link in links:
            try:
                return download_file_from_url(link, save_path=save_path)
            except Exception as e:
                errors.append(f'{link}, error: {e}\n')
                continue

        raise WFTError(f"Failed to download from all links:\n{''.join(errors)}")
